UPDATE CHB_MKT_HOLIDAY as T, ( select BUSI_DATE, MARKET_CODE from ( select TEMP.* from (
SELECT #{item,jdbcType=DATE} AS BUSI_DATE, #{marketCalendarType} AS MARKET_CODE FROM DUAL
) TEMP ) de ) AS T1 set T.IS_HOLIDAY = #{isHoliday} where T1.BUSI_DATE = T.BUSI_DATE AND T1.MARKET_CODE = T.MARKET_CODE;
insert into CHB_MKT_HOLIDAY( BUSI_DATE,
MARKET_CODE,
IS_HOLIDAY,
DEPT_CODE,
STATUS,CREATE_TIME,
CREATE_USER
) select BUSI_DATE, MARKET_CODE from( select TEMP.* from (
SELECT #{item,jdbcType=DATE} AS BUSI_DATE, #{marketCalendarType} AS MARKET_CODE FROM DUAL
) TEMP where not exists (select 1 from CHB_MKT_HOLIDAY CII where CII.BUSI_DATE = TEMP.BUSI_DATE AND CII.MARKET_CODE = TEMP.MARKET_CODE ) ) de ;
